import{_ as t,c as r,o as n,ag as i}from"./chunks/framework.bCALENAD.js";const s="/assets/interface.BIKxuCLo.png",a="/assets/latest.Diuf8Ogd.png",l="/assets/tests.BHpC1p5M.png",m=JSON.parse('{"title":"Die Benutzeroberfläche","description":"","frontmatter":{},"headers":[],"relativePath":"de/instructions/main.md","filePath":"de/instructions/main.md","lastUpdated":1720814203000}'),o={name:"de/instructions/main.md"};function c(d,e,h,u,f,p){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="die-benutzeroberflache" tabindex="-1">Die Benutzeroberfläche <a class="header-anchor" href="#die-benutzeroberflache" aria-label="Permalink to &quot;Die Benutzeroberfläche&quot;">​</a></h1><p>Die Benutzeroberfläche von MySpeed wurde von Grund auf benutzerfreundlich gestaltet. Um jedoch mögliche Verwirrung zu vermeiden, ist hier alles erklärt.</p><h2 id="die-benutzeroberflache-1" tabindex="-1">Die Benutzeroberfläche <a class="header-anchor" href="#die-benutzeroberflache-1" aria-label="Permalink to &quot;Die Benutzeroberfläche&quot;">​</a></h2><p><img src="'+s+'" alt="MySpeed Benutzeroberfläche"></p><p>Die Benutzeroberfläche von MySpeed ist in <strong>3</strong> Teile unterteilt.</p><p>Der <strong>erste</strong> Teil ist der sogenannte Header und bietet direkten Zugriff auf die Einstellungen und den Start eines Geschwindigkeitstests. Die Einstellungen werden ausführlicher <a href="./settings">hier</a> beschrieben.</p><p>Der <strong>zweite</strong> Teil zeigt immer den neuesten Geschwindigkeitstest an.</p><p>Der <strong>dritte</strong> Teil zeigt alle erstellten Geschwindigkeitstests an.</p><h2 id="letzter-test" tabindex="-1">Letzter Test <a class="header-anchor" href="#letzter-test" aria-label="Permalink to &quot;Letzter Test&quot;">​</a></h2><p><img src="'+a+'" alt="Letzter Test"></p><p>Dieser Teil zeigt immer den neuesten, also zuletzt erstellten Geschwindigkeitstest an. Wenn du auf ein Symbol klickst, öffnet sich das entsprechende Hilfemenü mit weiteren Informationen.</p><h2 id="ubersicht-aller-tests" tabindex="-1">Übersicht aller Tests <a class="header-anchor" href="#ubersicht-aller-tests" aria-label="Permalink to &quot;Übersicht aller Tests&quot;">​</a></h2><p><img src="'+l+'" alt="Übersicht aller Tests"></p><p>Hier lassen sich alle Tests anzeigen, die erstellt wurden. Es lässt sich jetzt auch auf die Uhr links klicken, um einen Dialog mit weiteren Informationen zu öffnen. Dieser Dialog zeigt nun weitere Informationen über den Test und bietet sogar die Möglichkeit, ihn direkt zu löschen (falls nötig).</p>',14)])])}const b=t(o,[["render",c]]);export{m as __pageData,b as default};
